gd0(){return"\u0421\u0442\u0432\u0430\u0440\u0430\u0439\u0446\u0435 \u043d\u0435\u043a\u0430\u043b\u044c\u043a\u0456 \u043a\u0440\u044b\u043d\u0456\u0446 \u0434\u0430\u0445\u043e\u0434\u0443, \u043a\u0430\u043b\u0456 \u0432\u044b \u0431\u0443\u0434\u0437\u0435\u0446\u0435 \u0441\u0442\u0430\u0432\u0456\u0446\u0446\u0430 \u0434\u0430 \u0433\u044d\u0442\u0430\u0433\u0430 \u043f\u0440\u0430\u0444\u0435\u0441\u0456\u0439\u043d\u0430. \u0413\u044d\u0442\u0430 \u043c\u043e\u0436\u0430 \u0441\u0442\u0430\u0446\u044c \u0434\u0430\u0434\u0430\u0442\u043a\u043e\u0432\u0430\u0439 \u043f\u0440\u0430\u0446\u0430\u0439 \u0430\u0431\u043e \u043f\u043e\u045e\u043d\u0430\u0446\u044d\u043d\u043d\u0430\u0439 \u043f\u0440\u0430\u0446\u0430\u0439 \u0437 \u0432\u044f\u043b\u0456\u043a\u0456\u043c \u0434\u0430\u0445\u043e\u0434\u0430\u043c."},
gez(){return"\u041a\u0430\u043b\u0456 \u045e \u0432\u0430\u0441 \u0451\u0441\u0446\u044c \u043f\u044b\u0442\u0430\u043d\u043d\u0456 \u0430\u0431 \u043d\u0430\u0448\u0430\u0439 \u043a\u0430\u043c\u043f\u0430\u043d\u0456\u0456, \u0432\u044b \u043c\u043e\u0436\u0430\u0446\u0435 \u043d\u0430\u043f\u0456\u0441\u0430\u0446\u044c \u043d\u0430\u043c \u043f\u0440\u0430\u0437 \u043d\u0430\u0441\u0442\u0443\u043f\u043d\u0443\u044e \u0444\u043e\u0440\u043c\u0443."},
