gdY(){return"\u0410\u043a\u043e \u0441\u0442\u0435 \u0432\u0440\u0430\u0431\u043e\u0442\u0435\u043d \u0432\u043e Edhomy, \u0432\u0435 \u043c\u043e\u043b\u0438\u043c\u0435 \u043f\u0440\u0438\u0458\u0430\u0432\u0435\u0442\u0435 \u0441\u0435 \u0437\u0430 \u0434\u0430 \u043f\u0440\u0438\u0441\u0442\u0430\u043f\u0438\u0442\u0435"},
geL(){return"\u041a\u043e\u0440\u0438\u0441\u043d\u0438\u0447\u043a\u043e \u0438\u043c\u0435 \u0438 \u043b\u043e\u0437\u0438\u043d\u043a\u0430"},
geO(){return"\u041d\u0430\u043f\u0438\u0448\u0435\u0442\u0435 \u0433\u043e \u043a\u043e\u0440\u0438\u0441\u043d\u0438\u0447\u043a\u043e\u0442\u043e \u0438\u043c\u0435 \u043e\u0432\u0434\u0435"},
gef(){return"\u041d\u0430\u043f\u0438\u0448\u0435\u0442\u0435 \u0458\u0430 \u043b\u043e\u0437\u0438\u043d\u043a\u0430\u0442\u0430 \u043e\u0432\u0434\u0435"},
gdI(a){return"\u041f\u043e\u0442\u0432\u0440\u0434\u0438"},
geG(){return"\u041a\u043e\u0440\u0438\u0441\u043d\u0438\u0447\u043a\u043e\u0442\u043e \u0438\u043c\u0435 \u0438\u043b\u0438 \u043b\u043e\u0437\u0438\u043d\u043a\u0430\u0442\u0430 \u043d\u0435 \u0441\u0435 \u0432\u0430\u043b\u0438\u0434\u043d\u0438. \u0412\u0435 \u043c\u043e\u043b\u0438\u043c\u0435 \u043a\u043e\u043d\u0442\u0430\u043a\u0442\u0438\u0440\u0430\u0458\u0442\u0435 \u0433\u043e \u0432\u0430\u0448\u0438\u043e\u0442 \u0441\u0443\u043f\u0435\u0440\u0432\u0430\u0439\u0437\u043e\u0440"},
gev(){return"\u0412\u0435 \u043c\u043e\u043b\u0438\u043c\u0435 \u0432\u043d\u0435\u0441\u0435\u0442\u0435 \u0433\u043e \u043a\u043e\u0440\u0438\u0441\u043d\u0438\u0447\u043a\u043e\u0442\u043e \u0438\u043c\u0435 \u0438 \u043b\u043e\u0437\u0438\u043d\u043a\u0430\u0442\u0430 \u043f\u0440\u0430\u0432\u0438\u043b\u043d\u043e"},
gcK(){return"\u041e\u0434\u0458\u0430\u0432\u0438 \u0441\u0435"},
