gcI(){return"\u043f\u043e\u0432\u0435\u045c\u0435"},
gcH(){return"\u043f\u043e\u043c\u0430\u043b\u043a\u0443"},
ge9(){return"\u0423\u0447\u0435\u0441\u043d\u0438\u0446\u0438"},
